package e.e.a;import android.preference.*;import java.util.*;
public final class OtherSettingsOrderTest {static int checks;static void check(boolean v,String why){checks++;if(!v)throw new AssertionError(why);}static Preference item(PreferenceActivity a,PreferenceGroup g,String key,int order){Preference p=new Preference(a);p.setKey(key);p.setOrder(order);g.addPreference(p);return p;}public static void main(String[] args){PreferenceActivity a=new PreferenceActivity();PreferenceGroup other=new PreferenceGroup(a),comment=new PreferenceGroup(a);a.getPreferenceScreen().addPreference(other);a.getPreferenceScreen().addPreference(comment);Preference filter=item(a,other,"nicoid_filter_list",0),ng=item(a,comment,"nicoid_ng_comments",10);item(a,other,"search_suggestions_enabled",2);item(a,other,"show_shorts_menu",3);item(a,other,"video_info_follow_button",4);SettingsTools.arrangeOther(a.getPreferenceScreen(),other);List<Preference> rows=new ArrayList<>(other.entries);rows.sort((x,y)->Integer.compare(x.getOrder(),y.getOrder()));check(rows.get(0)==filter&&rows.get(1)==ng,"NG list must immediately follow content filter after all controls moved");check(!comment.entries.contains(ng),"NG list is outside Comment category");check(rows.size()==5,"all other controls retained");SettingsTools.arrangeOther(a.getPreferenceScreen(),other);check(other.entries.size()==5,"ordering does not duplicate entries");System.out.println("Other settings order: "+checks+" adjacency/retention checks passed");}}
